<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login history — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="shell"><nav class="nav"><a class="brand" href="/dashboard">c0m.me</a><a class="nav-link" href="/sessions">Active devices</a></nav><section class="hero compact"><span class="eyebrow">ACCOUNT SECURITY</span><h1>Login history</h1><p>Recent successful sign-ins associated with this account.</p></section><section class="feature-grid" style="grid-template-columns:1fr"><?php foreach ($history as $item): ?><article><b><?= $item['success'] ? 'SUCCESSFUL SIGN-IN' : 'FAILED SIGN-IN' ?></b><p><?= htmlspecialchars($item['ip_display'], ENT_QUOTES, 'UTF-8') ?><br><?= htmlspecialchars($item['user_agent'] ?: 'Unknown browser', ENT_QUOTES, 'UTF-8') ?><br><?= htmlspecialchars($item['created_at'], ENT_QUOTES, 'UTF-8') ?></p></article><?php endforeach; ?><?php if (!$history): ?><article><p>No login history is available yet.</p></article><?php endif; ?></section></main></body></html>
